arguments.command:
mkdir -p /app/bs && cat > /app/bs/bs.py <<'EOF'
import numpy as np, itertools, json, sys
N=6
def places(L):
    out=[]
    for r in range(N):
        for c in range(N):
            if c+L<=N: out.append((0,tuple((r,c+i) for i in range(L))))
            if r+L<=N and L>1: out.append((1,tuple((r+i,c) for i in range(L))))
    return out
P={L:places(L) for L in (4,3,2)}
def nb(cells):
    s=set()
    for r,c in cells:
        for dr in (-1,0,1):
            for dc in (-1,0,1): s.add((r+dr,c+dc))
    return s
lays=[];R=[]
center={(2,2),(2,3),(3,2),(3,3)}
for a in P[4]:
  for b in P[3]:
    if set(a[1])&set(b[1]): continue
    for d in P[2]:
      if set(d[1])&(set(a[1])|set(b[1])): continue
      ships=[a,b,d]
      cells=set(a[1])|set(b[1])|set(d[1])
      g=np.zeros(36,bool)
      for r,c in cells: g[r*6+c]=1
      t=[[bool(nb(ships[i][1])&set(ships[j][1])) for j in range(3)] for i in range(3)]
      notouch=not(t[0][1] or t[0][2] or t[1][2])
      par=a[0]==b[0]==d[0]
      border=all(any(r in(0,5) or c in(0,5) for r,c in s[1]) for s in ships)
      cc=not(cells&center)
      cl=all(any(t[i][j] for j in range(3) if j!=i) for i in range(3))
      lays.append(g);R.append([True,notouch,par,border,cc,cl])
G=np.array(lays,float);R=np.array(R,float)
names=["any","no_touch","parallel","border","center_clear","clustered"]
print(len(G),R.sum(0),file=sys.stderr)
W=R/R.sum(0)/6   # joint weights layouts x rules
def lik_fire(o,cell): p=G[:,cell]; return np.where(p==1,0.9 if o else 0.1,0.1 if o else 0.9)
def scan_counts(axis,i):
    idx=[i*6+c for c in range(6)] if axis=="row" else [r*6+i for r in range(6)]
    return G[:,idx].sum(1).astype(int)
def lik_scan(o,cnt):
    l=np.zeros(len(cnt))
    for d,p in((-1,.15),(0,.7),(1,.15)):
        l+=p*(np.clip(cnt+d,0,6)==o)
    return l
obs=json.load(open('/app/bs/obs.json')) if len(sys.argv)<2 or True else []
J=W.copy()
for o in obs:
    if o[0]=="fire": J*=lik_fire(o[3],o[1]*6+o[2])[:,None]
    else: J*=lik_scan(o[3],scan_counts(o[1],o[2]))[:,None]
J/=J.sum()
pr=J.sum(0);pl=J.sum(1);occ=pl@G
print("rules",dict(zip(names,np.round(pr,3))))
print(np.round(occ.reshape(6,6),3))
prior=np.array(json.load(open('/app/bs/prior.json'))).ravel()
def H(p): p=np.clip(p,1e-12,1-1e-12); return -(p*np.log(p)+(1-p)*np.log(1-p))
def score_val(J):
    # expected score proxy: rule entropy/log6 + cell entropy/20.12
    pr=J.sum(0);pl=J.sum(1);occ=pl@G
    return -(-(pr*np.log(pr+1e-15)).sum()/np.log(6)+H(occ).sum()/20.1236)/2
res=[]
for cell in range(36):
    ev=0
    for o in (0,1):
        Jo=J*lik_fire(o,cell)[:,None];po=Jo.sum()
        ev+=po*score_val(Jo/po)
    res.append((ev,1,"fire",cell//6,cell%6))
for axis in("row","col"):
    for i in range(6):
        cnt=scan_counts(axis,i);ev=0
        for o in range(7):
            Jo=J*lik_scan(o,cnt)[:,None];po=Jo.sum()
            if po>1e-12: ev+=po*score_val(Jo/po)
        res.append((ev,2,axis,i,None))
base=score_val(J)
res=sorted(res,key=lambda x:-(x[0]-base)/x[1])
for r in res[:6]: print(round((r[0]-base)/r[1],4),r[2:])
json.dump({"rules":dict(zip(names,pr.tolist())),"occ":occ.reshape(6,6).tolist()},open('/app/bs/post.json','w'))
